    #[test]
    fn dep_key_reads_only_dependency_lines() {
        assert_eq!(
            dep_key("embassy-stm32 = { version = \"0.6\" }"),
            Some("embassy-stm32")
        );
        assert_eq!(dep_key("  cortex-m    = \"0.7\""), Some("cortex-m"));
        assert_eq!(dep_key("# a comment"), None);
        assert_eq!(dep_key("[dependencies]"), None);
        assert_eq!(dep_key(""), None);
        assert_eq!(dep_key("features = [\"a\"] }"), Some("features"));
    }

    /// The reported bug: on a chip whose HAL is NOT `stm32f1xx-hal` (every STM32
    /// but F1), each call appended `usb-device` + `usbd-serial` again — and since
    /// dragging a module box bumps the regeneration hash, one drag wrote dozens
    /// of duplicate lines. Every USB test until now used an F1 manifest, where
    /// the `stm32-usbd` feature lands on the HAL line and closes the guard.
    #[test]
    fn usb_deps_are_idempotent_without_an_f1_hal_line() {
        let base = "[package]\nname = \"h5\"\n\n[dependencies]\n\
                    embassy-stm32 = { version = \"0.6\", features = [\"stm32h563zi\"] }\n";
        let once = ensure_usb_deps(base, true, &[]);
        assert_eq!(
            once.lines()
                .filter(|l| is_dep_line(l, "usb-device"))
                .count(),
            1,
            "the first call adds it once:\n{once}"
        );

        // Ten more calls — a fraction of one drag — must change nothing.
        let mut s = once.clone();
        for _ in 0..10 {
            s = ensure_usb_deps(&s, true, &[]);
        }
        assert_eq!(s, once, "repeated calls must be a no-op:\n{s}");
        assert_eq!(
            s.lines().filter(|l| is_dep_line(l, "usbd-serial")).count(),
            1
        );

        // And removal still works from that state.
        let off = ensure_usb_deps(&s, false, &[]);
        assert!(!off.lines().any(|l| is_dep_line(l, "usb-device")), "{off}");
        assert!(!off.lines().any(|l| is_dep_line(l, "usbd-serial")), "{off}");
    }

    /// The F1 path — where the `stm32-usbd` HAL feature IS part of the state —
    /// keeps working exactly as before.
    #[test]
    fn usb_deps_still_toggle_the_f1_hal_feature() {
        let base = "[package]\nname = \"f1\"\n\n[dependencies]\n\
                    stm32f1xx-hal = { version = \"0.10\", features = [\"stm32f103\", \"rt\"] }\n";
        let on = ensure_usb_deps(base, true, &[]);
        assert!(on.contains("\"stm32-usbd\""), "feature added:\n{on}");
        assert_eq!(
            on.lines().filter(|l| is_dep_line(l, "usb-device")).count(),
            1
        );
        // Idempotent here too.
        assert_eq!(ensure_usb_deps(&on, true, &[]), on);

        let off = ensure_usb_deps(&on, false, &[]);
        assert!(!off.contains("\"stm32-usbd\""), "feature removed:\n{off}");
        assert!(!off.lines().any(|l| is_dep_line(l, "usb-device")));
    }

    /// A duplicate that a previous build already wrote must not survive a
    /// removal pass — the loop drops every matching IDE-owned line, not one.
    #[test]
    fn removal_cleans_up_lines_an_older_build_duplicated() {
        let mut s = String::from("[package]\nname = \"h5\"\n\n[dependencies]\n");
        for _ in 0..5 {
            s.push_str(&format!("usb-device  = \"0.2\"   {DEP_MARKER}\n"));
            s.push_str(&format!("usbd-serial = \"0.1\"   {DEP_MARKER}\n"));
        }
        let off = ensure_usb_deps(&s, false, &[]);
        assert!(
            !off.lines().any(|l| is_dep_line(l, "usb-device")),
            "all copies go, not just the first:\n{off}"
        );
    }

    #[test]
    fn blocking_gpio_keeps_embedded_hal_through_the_async_pass() {
        // Blocking GPIO (io.rs) pulls embedded-hal 1.0 via `ensure_peripheral_deps`.
        let base = "[package]\nname = \"x\"\n\n[dependencies]\ncortex-m = \"0.7\"\n";
        let with_gpio = ensure_peripheral_deps(base, false, false, false, false, true, false, &[]);
        assert!(
            with_gpio.lines().any(|l| is_dep_line(l, "embedded-hal")),
            "peripheral deps add embedded-hal for GPIO:\n{with_gpio}"
        );
        // The async pass runs next and ALSO manages embedded-hal — it must be told
        // the blocking need (combined), or it strips what was just added.
        let after_async = ensure_async_deps(
            &with_gpio,
            false,
            AsyncFlavor::Stm32,
            false,
            true,
            false,
            &[],
        );
        assert!(
            after_async.lines().any(|l| is_dep_line(l, "embedded-hal")),
            "async pass keeps embedded-hal when the combined need is true:\n{after_async}"
        );
        // Guard proving the bug shape: the OLD `needs_eh = false` stripped it.
        let stripped = ensure_async_deps(
            &with_gpio,
            false,
            AsyncFlavor::Stm32,
            false,
            false,
            false,
            &[],
        );
        assert!(
            !stripped.lines().any(|l| is_dep_line(l, "embedded-hal")),
            "needs_eh=false would strip it (the bug this guards):\n{stripped}"
        );
    }

    /// The whole point of parking the old value in the marker: turning the
    /// toggle back off has to restore the project's OWN profile, including
    /// values the user typed, and leave the file byte-identical.
    #[test]
    fn debug_build_round_trips_the_release_profile() {
        let base = "[package]\nname = \"x\"\n\n[profile.release]\n\
                    panic         = \"abort\"\n\
                    codegen-units = 1\n\
                    debug         = true\n\
                    lto           = true\n\
                    opt-level     = \"s\"\n\
                    \n[profile.dev]\nopt-level = 1\n";

        let on = ensure_debug_build(base, true);
        // Overridden — and the file's column alignment is kept.
        assert!(on.contains("opt-level     = 1  "), "{on}");
        assert!(on.contains("debug         = true  "), "{on}");
        // Keys it does NOT own are left exactly as they were — `lto` above all:
        // dropping it is what overflows Flash on a 64 KB part.
        assert!(on.contains("lto           = true\n"), "{on}");
        assert!(on.contains("panic         = \"abort\"\n"), "{on}");
        assert!(on.contains("codegen-units = 1\n"), "{on}");
        // The other profile is never touched.
        assert!(on.contains("[profile.dev]\nopt-level = 1"), "{on}");
        // Idempotent, and the ORIGINAL line survives a second pass.
        assert_eq!(ensure_debug_build(&on, true), on);
        assert!(
            on.contains("was: opt-level     = \"s\">"),
            "original parked verbatim:\n{on}"
        );

        // Off → exactly the file we started from.
        assert_eq!(ensure_debug_build(&on, false), base);
        // Off on an untouched file is a no-op.
        assert_eq!(ensure_debug_build(base, false), base);
    }

    /// A profile that lacks a key gets one while the toggle is on — and loses it
    /// again on the way out, rather than being left with an invented `debug`.
    #[test]
    fn debug_build_invents_and_removes_missing_keys() {
        let base = "[package]\nname = \"x\"\n\n[profile.release]\nopt-level = 3\n";
        let on = ensure_debug_build(base, true);
        assert!(
            on.contains(&format!("debug = true  {DEBUG_BUILD_TAG} absent>")),
            "{on}"
        );
        assert_eq!(ensure_debug_build(&on, false), base);

        // A user's custom value is restored verbatim, not replaced by a default.
        let custom = "[profile.release]\nopt-level = 3\nlto = \"fat\"\n";
        assert_eq!(
            ensure_debug_build(&ensure_debug_build(custom, true), false),
            custom
        );
    }

    /// A Cargo.toml with no release profile at all: one is created while on, and
    /// nothing happens while off (there is nothing to restore).
    #[test]
    fn debug_build_creates_a_missing_profile() {
        let base = "[package]\nname = \"x\"\n";
        assert_eq!(ensure_debug_build(base, false), base);
        let on = ensure_debug_build(base, true);
        assert_eq!(on.matches("[profile.release]").count(), 1, "{on}");
        assert!(on.contains("opt-level = 1"), "{on}");
        // Every key it invented is marked absent → the section empties out again.
        let off = ensure_debug_build(&on, false);
        assert!(!off.contains("opt-level"), "{off}");
        assert!(!off.contains("debug"), "{off}");
    }

    /// An `lto = false` written by the FIRST version of this toggle (which owned
    /// that key and made mid-size projects overflow Flash) is handed back on the
    /// next pass, whichever way the toggle is set.
    #[test]
    fn debug_build_restores_legacy_lto_override() {
        let legacy = format!(
            "[profile.release]\nopt-level     = 1  {DEBUG_BUILD_TAG} opt-level     = \"s\">\n\
             lto           = false  {DEBUG_BUILD_TAG} lto           = true>\n"
        );
        for on in [true, false] {
            let fixed = ensure_debug_build(&legacy, on);
            assert!(
                fixed.contains("lto           = true\n"),
                "lto handed back (on={on}):\n{fixed}"
            );
            assert!(!fixed.contains("lto           = false"), "{fixed}");
        }
        // With the toggle off, the whole profile is the user's own again.
        assert_eq!(
            ensure_debug_build(&legacy, false),
            "[profile.release]\nopt-level     = \"s\"\nlto           = true\n"
        );
    }

    #[test]
    fn strict_lints_add_remove_is_idempotent() {
        let base = "[package]\nname = \"x\"\n\n[dependencies]\ncortex-m = \"0.7\"\n";
        // Enable → block present, once.
        let on = ensure_strict_lints(base, true);
        assert!(on.contains("[lints.clippy]"), "block added:\n{on}");
        assert!(on.contains("unwrap_used = \"deny\""));
        assert!(on.contains("as_conversions = \"deny\""));
        assert_eq!(on.matches("[lints.clippy]").count(), 1);
        // Enabling again doesn't duplicate.
        assert_eq!(ensure_strict_lints(&on, true), on);
        // Disable → back to exactly the original (block + its markers gone).
        let off = ensure_strict_lints(&on, false);
        assert!(!off.contains("[lints.clippy]"), "block removed:\n{off}");
        assert!(!off.contains("strict-lints"), "markers removed:\n{off}");
        assert_eq!(off, base);
        // Disabling a base without the block is a no-op.
        assert_eq!(ensure_strict_lints(base, false), base);
    }

    #[test]
    fn strict_lints_dedupes_block_with_lost_begin_marker() {
        // The reported bug: a strict block whose BEGIN marker went missing (only
        // the END marker survived) wasn't recognised, so each Save appended a new
        // `[lints.clippy]` → several stacked. The END-anchored strip must remove
        // such an orphaned block (and any duplicates) and leave exactly one.
        let base = "[package]\nname = \"x\"\n";
        let orphan = format!(
            "{base}\n[lints.clippy]\nunwrap_used = \"deny\"\npanic = \"deny\"\n{END}\n\
             \n[lints.clippy]\nunwrap_used = \"deny\"\npanic = \"deny\"\n{END}\n",
            END = STRICT_LINTS_END,
        );
        let fixed = ensure_strict_lints(&orphan, true);
        assert_eq!(
            fixed.matches("[lints.clippy]").count(),
            1,
            "exactly one block after re-enable:\n{fixed}"
        );
        assert_eq!(fixed.matches(STRICT_LINTS_END).count(), 1);
        // And toggling it off clears the orphaned blocks entirely.
        let off = ensure_strict_lints(&orphan, false);
        assert!(
            !off.contains("[lints.clippy]"),
            "all blocks removed:\n{off}"
        );
        assert_eq!(off, base);
    }

    #[test]
    fn strict_block_survives_full_save_open_extract_cycle() {
        // Regression / root-cause guard for the "multiple [lints.clippy]" bug.
        // Proves the whole in-app pipeline PRESERVES the strict block's markers:
        // generate → enable strict → open (splice refreshes the GENERATED block)
        // → extract a lib (add workspace member) → un-extract (remove it, leaving
        // `members = []`, the shape from the bug report) → open again → re-enable.
        // The BEGIN marker survives every step, so exactly ONE block remains — the
        // orphaned blocks in the wild came from an EXTERNAL edit dropping the
        // marker comment, not from this code (which the END-anchored strip + ASCII
        // marker now tolerate anyway).
        use crate::panels::mcu_module::mcu_catalog::ToolchainKind;
        use crate::project_tree::extract_crate::{add_workspace_member, remove_workspace_member};
        let def = stm32_def();
        let tc = ToolchainKind::RustEmbedded;

        let mut toml = ensure_strict_lints(&gen_config(ConfigFile::CargoToml, &def, &tc), true);
        for step in [
            "generate+enable",
            "open",
            "extract",
            "un-extract",
            "reopen",
            "re-enable",
        ] {
            toml = match step {
                "open" | "reopen" => splice_config(ConfigFile::CargoToml, &toml, &def, &tc),
                "extract" => add_workspace_member(&toml, "mylib"),
                "un-extract" => remove_workspace_member(&toml, "mylib"),
                "re-enable" => ensure_strict_lints(&toml, true),
                _ => toml,
            };
            assert!(
                toml.contains(STRICT_LINTS_BEGIN),
                "BEGIN marker lost after `{step}`:\n{toml}"
            );
            assert_eq!(
                toml.matches("[lints.clippy]").count(),
                1,
                "exactly one block after `{step}`:\n{toml}"
            );
        }
    }

